def f(g):
    from collections import Counter
    B=Counter(x for r in g for x in r).most_common(1)[0][0]
    H,W=len(g),len(g[0]); O=[r[:] for r in g]
    pts=[(r,c,g[r][c]) for r in range(H) for c in range(W) if g[r][c]!=B]
    for p in pts:
        v=p[2]; best=None
        for dr,dc in ((-1,-1),(-1,1),(1,-1),(1,1)):
            rr,cc2=p[0]+dr,p[1]+dc; cnt=0
            while 0<=rr<H and 0<=cc2<W and g[rr][cc2]==B:
                cnt+=1; rr+=dr; cc2+=dc
            if best is None or (cnt,dr,dc)>best: best=(cnt,dr,dc)
        cnt,dr,dc=best
        if cnt>0:
            rr,cc2=p[0]+dr,p[1]+dc
            while 0<=rr<H and 0<=cc2<W and g[rr][cc2]==B:
                O[rr][cc2]=v; rr+=dr; cc2+=dc
    return O
